<?php
namespace AdmidioPlugin\EventAttendance\Presenter;
use Admidio\Infrastructure\Utils\SecurityUtils;
use Admidio\UI\Presenter\FormPresenter;
use Admidio\UI\Presenter\PagePresenter;
final class AttendanceFormPresenter { /** @param array<int,array<string,mixed>> $roster */ public function create(PagePresenter $page, string $url, string $cancelUrl, array $roster): void { global $gCurrentSession, $gL10n; $form = new FormPresenter('adm_event_attendance_form', 'plugin.event-attendance.attendance.edit.tpl', SecurityUtils::encodeUrl($url)); $rows = []; foreach ($roster as $person) { $field = 'attendance_status_' . (int)$person['eau_usr_id']; $form->addSelectBox($field, '', ['' => $gL10n->get('SYS_EVENT_ATTENDANCE_UNKNOWN'), 'present' => $gL10n->get('SYS_EVENT_ATTENDANCE_PRESENT'), 'excused' => $gL10n->get('SYS_EVENT_ATTENDANCE_EXCUSED'), 'absent' => $gL10n->get('SYS_EVENT_ATTENDANCE_ABSENT')], ['defaultValue' => $person['ear_status'] ?? '', 'showContextDependentFirstEntry' => false]); $rows[] = ['name' => trim($person['first_name'] . ' ' . $person['last_name']), 'field' => $field]; } $form->addSubmitButton('adm_button_save_attendance', $gL10n->get('SYS_SAVE'), ['icon' => 'bi-check-lg', 'class' => 'offset-sm-3']); $form->addToSmarty($page->getSmartyTemplate()); $page->assignSmartyVariable('attendanceRows', $rows); $page->assignSmartyVariable('cancelUrl', SecurityUtils::encodeUrl($cancelUrl)); $gCurrentSession->addFormObject($form); $page->addTemplateFile('plugin.event-attendance.attendance.edit.tpl'); } }
